    $p('peripherie', 'B07W6HMG1C', 'Logitech', 'tastatur,mechanisch,kabellos', $t(
        'logitech-mx-mechanical',
        'Logitech MX Mechanical',
        'Flache mechanische Funktastatur: präziser Anschlag für Vieltipper, bis zu drei Geräte.',
        'Logitech MX Mechanical eingeschätzt: flache mechanische Funktastatur mit Beleuchtung und Ziffernblock für bis zu drei Geräte. Für alle, die viel tippen.',
        'Die MX Mechanical ist eine flache, kabellose Tastatur mit mechanischen Schaltern und Ziffernblock. Jeder Anschlag ist klar spürbar, was beim Vieltippen weniger ermüdet. Sie wechselt zwischen bis zu drei Geräten.',
        [['Schalter', 'flache mechanische Schalter, je nach Variante'], ['Verbindung', 'Bluetooth oder Logi-Bolt-Empfänger, bis zu 3 Geräte'], ['Beleuchtung', 'ja, mit Näherungssensor'], ['Bauform', 'volle Größe mit Ziffernblock']],
        [['Ist sie laut?', 'Lauter als eine flache Bürotastatur. Die taktile Variante ist ein guter Kompromiss für Großraumbüros.'], ['Welche Schalter soll ich nehmen?', 'Taktil für spürbaren, leisen Druckpunkt, linear für gleichmäßigen Anschlag, Clicky nur im Einzelbüro.'], ['Gibt es eine kleinere Version?', 'Ja, die MX Mechanical Mini ohne Ziffernblock.']],
        $bodyDe('Mechanische Tastaturen sind nicht nur für Gamer. Wer täglich Stunden schreibt, merkt den klaren Anschlag schnell. Die MX Mechanical bringt das in Bürooptik.', ['Präziser, gleichmäßiger Anschlag', 'Flache Bauform ohne Handballenauflage nötig', 'Geräte-Umschaltung wie bei der MX-Serie gewohnt'], ['Lauter als Rubberdome-Tastaturen', 'Schalterart beim Kauf bewusst wählen'], 'Für Selbstständige und Teams, die viel schreiben und ein spürbares Tippgefühl schätzen.'),
    ), $t(
        'logitech-mx-mechanical-keyboard',
        'Logitech MX Mechanical',
        'Low-profile mechanical wireless keyboard: precise keystrokes for heavy typists, up to three devices.',
        'Logitech MX Mechanical assessed: low-profile mechanical wireless keyboard with backlight and number pad for up to three devices. For people who type a lot.',
        'The MX Mechanical is a low-profile wireless keyboard with mechanical switches and a number pad. Every keystroke is clearly felt, which tires less during long typing. It switches between up to three devices.',
        [['Switches', 'low-profile mechanical, depending on variant'], ['Connection', 'Bluetooth or Logi Bolt receiver, up to 3 devices'], ['Backlight', 'yes, with proximity sensor'], ['Form', 'full size with number pad']],
        [['Is it loud?', 'Louder than a flat office keyboard. The tactile variant is a good compromise for open-plan offices.'], ['Which switches should I choose?', 'Tactile for a noticeable, quiet bump, linear for an even stroke, clicky only in a private office.'], ['Is there a smaller version?', 'Yes, the MX Mechanical Mini without number pad.']],
        $bodyEn('Mechanical keyboards are not just for gamers. Anyone who writes for hours every day soon notices the clear keystroke. The MX Mechanical brings that in an office look.', ['Precise, even keystroke', 'Low profile, no wrist rest needed', 'Device switching as known from the MX range'], ['Louder than rubber-dome keyboards', 'Choose the switch type deliberately'], 'Freelancers and teams who write a lot and appreciate a tangible typing feel.'),
    )),
    $p('peripherie', 'B0DB2HLSS9', 'Logitech', 'trackball,maus,ergonomie', $t(
        'logitech-mx-ergo-s',
        'Logitech MX Ergo S Trackball',
        'Trackball mit neigbarem Gehäuse: der Arm bleibt ruhig, der Daumen steuert.',
        'Logitech MX Ergo S eingeschätzt: kabelloser Daumen-Trackball mit verstellbarem Neigungswinkel und leisen Tasten. Eine Alternative bei Beschwerden im Handgelenk.',
        'Die MX Ergo S ist ein kabelloser Trackball: Der Zeiger wird mit dem Daumen über eine Kugel gesteuert, Hand und Arm bleiben liegen. Das Gehäuse lässt sich neigen, die Tasten klicken leise.',
        [['Bedienung', 'Daumen-Trackball'], ['Ergonomie', 'Neigung verstellbar'], ['Verbindung', 'Bluetooth, Umschaltung zwischen 2 Geräten'], ['Laden', 'USB-C']],
        [['Wie lange dauert die Umgewöhnung?', 'Meist einige Tage. Danach ist die Steuerung genauso präzise wie mit einer Maus.'], ['Hilft das bei Sehnenscheidenentzündung?', 'Viele empfinden die ruhige Hand als Entlastung. Bei Beschwerden klären Sie das bitte ärztlich ab.'], ['Braucht er Platz?', 'Nein. Er bleibt an Ort und Stelle liegen und braucht kein Mauspad.']],
        $bodyDe('Wer bei der Maus Schmerzen im Handgelenk oder in der Schulter spürt, findet mit einem Trackball oft Ruhe. Die MX Ergo S ist eines der bequemsten Modelle.', ['Arm und Handgelenk bewegen sich kaum', 'Neigbares Gehäuse für eine natürlichere Handhaltung', 'Leise Tasten'], ['Umgewöhnung von einigen Tagen', 'Nur für Rechtshänder'], 'Für Vielarbeiter am Rechner mit Beschwerden durch die Maus und für sehr enge Schreibtische.'),
    ), $t(
        'logitech-mx-ergo-s-trackball',
        'Logitech MX Ergo S trackball',
        'Trackball with a tilting body: the arm stays still, the thumb steers.',
        'Logitech MX Ergo S assessed: wireless thumb trackball with adjustable tilt and quiet buttons. An alternative when the wrist starts to hurt.',
        'The MX Ergo S is a wireless trackball: the pointer is steered with the thumb on a ball while hand and arm stay put. The body can be tilted, and the buttons click quietly.',
        [['Operation', 'thumb trackball'], ['Ergonomics', 'adjustable tilt'], ['Connection', 'Bluetooth, switching between 2 devices'], ['Charging', 'USB-C']],
        [['How long does it take to get used to?', 'Usually a few days. After that it is as precise as a mouse.'], ['Does it help with tendon problems?', 'Many find the still hand a relief. If you have symptoms, please see a doctor.'], ['Does it need space?', 'No. It stays in place and needs no mouse pad.']],
        $bodyEn('Anyone who feels pain in the wrist or shoulder from a mouse often finds relief with a trackball. The MX Ergo S is one of the most comfortable models.', ['Arm and wrist barely move', 'Tilting body for a more natural hand position', 'Quiet buttons'], ['A few days to get used to', 'Right-handed only'], 'Heavy computer users with mouse-related discomfort and very small desks.'),
    )),
    $p('peripherie', 'B09718MZQQ', 'CHERRY', 'tastatur,maus,set,kabellos', $t(
        'cherry-stream-desktop-recharge',
        'CHERRY Stream Desktop Recharge',
        'Leises Funkset aus Tastatur und Maus mit Akku: die solide Ausstattung für jeden Büroplatz.',
        'CHERRY Stream Desktop Recharge eingeschätzt: kabelloses Set aus leiser Tastatur mit Akku und Maus, deutsches Layout. Solide Grundausstattung fürs Büro.',
        'Das Stream Desktop Recharge ist ein kabelloses Set aus Tastatur und Maus mit deutschem Layout. Die Tastatur tippt leise und lädt per USB, ein Empfänger verbindet beides ohne Bluetooth-Kopplung.',
        [['Umfang', 'Tastatur und Maus'], ['Verbindung', 'Funk mit USB-Empfänger'], ['Layout', 'Deutsch (QWERTZ)'], ['Strom', 'Tastatur mit Akku']],
        [['Für wen lohnt sich ein Set statt MX-Tastatur?', 'Für Arbeitsplätze, an denen ein Gerät hängt und es vor allem zuverlässig sein soll.'], ['Brauche ich Bluetooth?', 'Nein. Der mitgelieferte Empfänger in einem USB-Port genügt.'], ['Ist sie leise?', 'Ja, die Tasten sind gedämpft und eignen sich für geteilte Büros.']],
        $bodyDe('Nicht jeder Arbeitsplatz braucht eine Premium-Tastatur. CHERRY ist der deutsche Klassiker für Büros, in denen Geräte einfach jahrelang funktionieren sollen.', ['Leiser Anschlag', 'Kein Batteriewechsel bei der Tastatur', 'Einstecken und loslegen, ohne Kopplung'], ['Nur ein Gerät pro Set', 'Einfache Maus ohne Zusatztasten'], 'Für die Ausstattung mehrerer Büroarbeitsplätze und für alle, die ein unkompliziertes Set suchen.'),
    ), $t(
        'cherry-stream-desktop-recharge-set',
        'CHERRY Stream Desktop Recharge',
        'Quiet wireless keyboard-and-mouse set with a rechargeable battery: solid kit for any office desk.',
        'CHERRY Stream Desktop Recharge assessed: wireless set of a quiet rechargeable keyboard and a mouse, German layout. Solid basic kit for the office.',
        'The Stream Desktop Recharge is a wireless keyboard-and-mouse set with a German layout. The keyboard types quietly and charges via USB, and one receiver connects both without Bluetooth pairing.',
        [['Contents', 'keyboard and mouse'], ['Connection', 'wireless with USB receiver'], ['Layout', 'German (QWERTZ)'], ['Power', 'rechargeable keyboard']],
        [['When is a set better than an MX keyboard?', 'At desks with one computer where reliability matters most.'], ['Do I need Bluetooth?', 'No. The included receiver in one USB port is enough.'], ['Is it quiet?', 'Yes, the keys are dampened and suit shared offices.']],
        $bodyEn('Not every desk needs a premium keyboard. CHERRY is the German classic for offices where devices should simply work for years.', ['Quiet keystroke', 'No battery swaps for the keyboard', 'Plug in and go, no pairing'], ['One device per set only', 'Basic mouse without extra buttons'], 'Equipping several office desks, and anyone looking for an uncomplicated set.'),
    )),
    $p('peripherie', 'B0CZ7L2QN1', 'Dell', 'monitor,27-zoll,usb-c', $t(
        'dell-p2725h',
        'Dell P2725H 27-Zoll-Monitor',
        '27 Zoll Full HD mit voll verstellbarem Fuß: der unkomplizierte Büromonitor.',
        'Dell P2725H eingeschätzt: 27-Zoll-Büromonitor mit IPS-Panel, USB-C und voll verstellbarem Standfuß. Wann Full HD auf 27 Zoll reicht.',
        'Der Dell P2725H ist ein 27-Zoll-Büromonitor mit Full-HD-Auflösung, IPS-Panel und USB-C. Der Standfuß lässt sich in Höhe, Neigung und Drehung verstellen, auch hochkant.',
        [['Größe', '27 Zoll, Full HD'], ['Panel', 'IPS, 100 Hz'], ['Anschlüsse', 'USB-C, HDMI, DisplayPort, USB-Hub'], ['Ergonomie', 'höhenverstellbar, neigbar, drehbar, Pivot']],
        [['Ist Full HD auf 27 Zoll scharf genug?', 'Für Office und Web ja, Schrift wirkt aber gröber als bei QHD. Wer viel mit Text arbeitet und nah sitzt, nimmt besser QHD.'], ['Lädt USB-C meinen Laptop?', 'Nur mit geringer Leistung. Für Laden über ein Kabel ist ein Monitor mit Power Delivery passender.'], ['Passt er an einen Monitorarm?', 'Ja, über VESA.']],
        $bodyDe('Dell-Monitore der P-Serie stehen in vielen Büros, weil Fuß, Anschlüsse und Garantie stimmen. Der P2725H ist das 27-Zoll-Einstiegsmodell.', ['Voll verstellbarer Standfuß', 'Viele Anschlüsse inklusive USB-Hub', 'Ruhiges, blickwinkelstabiles IPS-Bild'], ['Full HD auf 27 Zoll ist nicht besonders scharf', 'USB-C lädt Laptops nicht nennenswert'], 'Für Büroarbeitsplätze, an denen ein großer, ergonomischer Bildschirm wichtiger ist als höchste Schärfe.'),
    ), $t(
        'dell-p2725h-monitor',
        'Dell P2725H 27-inch monitor',
        '27-inch Full HD with a fully adjustable stand: the uncomplicated office monitor.',
        'Dell P2725H assessed: 27-inch office monitor with IPS panel, USB-C and a fully adjustable stand. When Full HD at 27 inches is enough.',
        'The Dell P2725H is a 27-inch office monitor with Full HD resolution, an IPS panel and USB-C. The stand adjusts in height, tilt and swivel, and it rotates to portrait.',
        [['Size', '27 inch, Full HD'], ['Panel', 'IPS, 100 Hz'], ['Ports', 'USB-C, HDMI, DisplayPort, USB hub'], ['Ergonomics', 'height, tilt, swivel, pivot']],
        [['Is Full HD sharp enough at 27 inches?', 'For office and web yes, but text looks coarser than on QHD. If you work with text and sit close, choose QHD.'], ['Does USB-C charge my laptop?', 'Only at low power. For one-cable charging, a monitor with power delivery fits better.'], ['Does it fit a monitor arm?', 'Yes, via VESA.']],
        $bodyEn('Dell P-series monitors sit in many offices because stand, ports and warranty are right. The P2725H is the 27-inch entry model.', ['Fully adjustable stand', 'Plenty of ports including a USB hub', 'Calm IPS picture with wide viewing angles'], ['Full HD at 27 inches is not especially sharp', 'USB-C does not meaningfully charge laptops'], 'Office desks where a large, ergonomic screen matters more than top sharpness.'),
    )),
