    $p('homeoffice', 'B0GGYLFHPS', 'Elgato', 'mikrofon,usb,videocall', $t(
        'elgato-wave-3-mk2',
        'Elgato Wave:3 MK.2 USB-Mikrofon',
        'USB-Mikrofon für klare Stimme in Calls, Webinaren und Aufnahmen, mit Stummschaltung oben.',
        'Elgato Wave:3 MK.2 eingeschätzt: USB-Kondensatormikrofon mit Software-Mixer für Calls, Webinare und Sprachaufnahmen. Wann es ein Headset übertrifft.',
        'Das Wave:3 MK.2 ist ein USB-Kondensatormikrofon für den Schreibtisch. Die Stimme klingt voll und natürlich, eine Software mischt Mikrofon und Systemton für Webinare und Aufnahmen.',
        [['Typ', 'Kondensatormikrofon, Niere'], ['Anschluss', 'USB-C'], ['Software', 'Elgato Wave Link mit Mixer'], ['Geeignet für', 'Webinare, Schulungen, Podcasts']],
        [['Brauche ich einen Mikrofonarm?', 'Nicht zwingend. Ein Arm bringt es aber näher an den Mund und hält Tischgeräusche fern.'], ['Nimmt es Tastaturgeräusche auf?', 'Etwas. Nah an der Stimme und von der Tastatur weggedreht bleibt das gering.'], ['Funktioniert es ohne Software?', 'Ja, als normales USB-Mikrofon. Die Software ist für Mixer und Effekte.']],
        $bodyDe('Wer regelmäßig Webinare gibt oder Schulungsvideos aufnimmt, merkt den Unterschied eines Standmikrofons sofort. Das Wave:3 ist dafür ein bewährter Klassiker in neuer Auflage.', ['Voller, natürlicher Klang', 'Stummschaltung direkt am Mikrofon', 'Mixer für Präsentationen mit Systemton'], ['Kondensator nimmt mehr Raum auf als ein dynamisches Mikrofon', 'Im Großraumbüro ist ein Headset die bessere Wahl'], 'Für Trainer, Berater und alle, die regelmäßig vor Publikum online sprechen.'),
    ), $t(
        'elgato-wave-3-mk2-microphone',
        'Elgato Wave:3 MK.2 USB microphone',
        'USB microphone for a clear voice in calls, webinars and recordings, with a mute on top.',
        'Elgato Wave:3 MK.2 assessed: USB condenser microphone with software mixer for calls, webinars and voice recordings. When it beats a headset.',
        'The Wave:3 MK.2 is a USB condenser microphone for the desk. Your voice sounds full and natural, and software mixes microphone and system sound for webinars and recordings.',
        [['Type', 'condenser, cardioid'], ['Connection', 'USB-C'], ['Software', 'Elgato Wave Link with mixer'], ['Suited to', 'webinars, trainings, podcasts']],
        [['Do I need a mic arm?', 'Not necessarily. An arm brings it closer to your mouth and keeps desk noise away.'], ['Does it pick up keyboard noise?', 'Somewhat. Close to your voice and turned away from the keyboard it stays low.'], ['Does it work without software?', 'Yes, as a normal USB microphone. The software is for the mixer and effects.']],
        $bodyEn('Anyone giving regular webinars or recording training videos notices the difference of a desk microphone at once. The Wave:3 is a proven classic in a new edition.', ['Full, natural sound', 'Mute right on the microphone', 'Mixer for presentations with system sound'], ['A condenser picks up more of the room than a dynamic microphone', 'In an open-plan office a headset is the better choice'], 'Trainers, consultants and anyone who speaks to an online audience regularly.'),
    )),
    $p('homeoffice', 'B0DSJM1832', 'Ergotron', 'monitorarm,ergonomie,dual', $t(
        'ergotron-lx-pro-dual-stacking',
        'Ergotron LX Pro Dual Stacking Monitorarm',
        'Zwei Monitore übereinander an einem Arm: mehr Bildfläche, ohne dass der Tisch breiter wird.',
        'Ergotron LX Pro Dual Stacking eingeschätzt: Monitorarm für zwei Bildschirme übereinander mit Federmechanik. Mehr Arbeitsfläche auf schmalem Tisch.',
        'Der LX Pro Dual Stacking ist ein Monitorarm für zwei Bildschirme übereinander. Beide lassen sich mit einer Hand verstellen, und der Schreibtisch bleibt frei. Ideal, wenn der Tisch für zwei Monitore nebeneinander zu schmal ist.',
        [['Monitore', '2, übereinander'], ['Größe', 'je bis 24 Zoll'], ['Mechanik', 'Feder, einhändig verstellbar'], ['Montage', 'Tischklemme oder Durchbohrung, VESA']],
        [['Ist übereinander nicht unbequem?', 'Der obere Monitor eignet sich für Nebeninfos wie Mail oder Chat. Er sollte leicht geneigt und nicht zu hoch sitzen.'], ['Passen meine Monitore?', 'Prüfen Sie VESA-Aufnahme, Größe und Gewicht. Größere Modelle brauchen einen anderen Arm.'], ['Hält die Klemme an jedem Tisch?', 'An stabilen Platten ja. Bei dünnen oder hohlen Platten hilft eine Verstärkungsplatte.']],
        $bodyDe('Zwei Monitore nebeneinander zwingen oft zu Kopfdrehungen und brauchen viel Tischbreite. Übereinander bleibt alles im Blickfeld.', ['Zwei Monitore auf der Breite von einem', 'Federarm von Ergotron, sehr langlebig', 'Freier Schreibtisch darunter'], ['Nur für kleinere Monitore', 'Oberer Bildschirm eher für Nebenaufgaben'], 'Für schmale Schreibtische und Arbeitsplätze, an denen ein zweiter Bildschirm für Mail oder Chat reicht.'),
    ), $t(
        'ergotron-lx-pro-dual-stacking-arm',
        'Ergotron LX Pro Dual Stacking monitor arm',
        'Two monitors stacked on one arm: more screen space without a wider desk.',
        'Ergotron LX Pro Dual Stacking assessed: monitor arm for two screens stacked with spring mechanics. More workspace on a narrow desk.',
        'The LX Pro Dual Stacking is a monitor arm for two screens stacked on top of each other. Both adjust with one hand, and the desk stays clear. Ideal when the desk is too narrow for two monitors side by side.',
        [['Monitors', '2, stacked'], ['Size', 'up to 24 inches each'], ['Mechanism', 'spring, one-hand adjustment'], ['Mounting', 'desk clamp or grommet, VESA']],
        [['Is stacking uncomfortable?', 'The upper monitor suits side information such as mail or chat. It should be tilted slightly and not sit too high.'], ['Will my monitors fit?', 'Check VESA mount, size and weight. Larger models need a different arm.'], ['Does the clamp hold on any desk?', 'On solid tops yes. On thin or hollow tops a reinforcement plate helps.']],
        $bodyEn('Two monitors side by side often force head turns and take a lot of desk width. Stacked, everything stays in view.', ['Two monitors in the width of one', 'Ergotron spring arm, very durable', 'Clear desk underneath'], ['For smaller monitors only', 'Upper screen better for secondary tasks'], 'Narrow desks and workstations where a second screen for mail or chat is enough.'),
    )),
    $p('homeoffice', 'B000GEBXHY', 'Fellowes', 'ergonomie,fussstuetze', $t(
        'fellowes-office-suites-fussstuetze',
        'Fellowes Office Suites Fußstütze',
        'Verstellbare Fußstütze: entlastet Beine und Rücken, wenn der Tisch nicht tiefer geht.',
        'Fellowes Office Suites Fußstütze eingeschätzt: höhen- und neigungsverstellbare Fußauflage für bessere Sitzhaltung. Kleine Anschaffung mit großer Wirkung.',
        'Die Office-Suites-Fußstütze von Fellowes ist in Höhe und Neigung verstellbar. Sie hilft, wenn die Füße bei richtig eingestelltem Stuhl nicht flach auf dem Boden stehen, und entlastet so Beine und Rücken.',
        [['Verstellung', 'Höhe und Neigung'], ['Oberfläche', 'rutschfest, antibakteriell behandelt'], ['Bewegung', 'feststellbar oder frei wippend'], ['Geeignet für', 'kleinere Menschen, nicht verstellbare Tische']],
        [['Brauche ich eine Fußstütze?', 'Wenn Ihre Füße bei passender Stuhlhöhe nicht flach aufstehen, ja. Sonst ist sie nicht nötig.'], ['Wippen oder feststellen?', 'Wippen hält die Beine in Bewegung, festgestellt gibt sie mehr Halt. Probieren Sie beides.'], ['Ersetzt sie einen verstellbaren Tisch?', 'Nein, aber sie gleicht einen zu hohen Tisch gut aus.']],
        $bodyDe('Viele Schreibtische haben eine feste Höhe, die für kleinere Menschen zu hoch ist. Eine Fußstütze ist die günstigste Korrektur.', ['Spürbar entspanntere Sitzhaltung', 'Verstellbar in Höhe und Winkel', 'Wippfunktion für Bewegung'], ['Nur sinnvoll, wenn die Füße sonst in der Luft hängen', 'Braucht Platz unter dem Tisch'], 'Für Arbeitsplätze mit fester Tischhöhe und für alle, deren Füße beim Sitzen nicht flach aufstehen.'),
    ), $t(
        'fellowes-office-suites-footrest',
        'Fellowes Office Suites footrest',
        'Adjustable footrest: relieves legs and back when the desk will not go lower.',
        'Fellowes Office Suites footrest assessed: height- and tilt-adjustable footrest for a better sitting posture. A small purchase with a big effect.',
        'The Fellowes Office Suites footrest adjusts in height and tilt. It helps when your feet do not rest flat on the floor with the chair set correctly, and so relieves legs and back.',
        [['Adjustment', 'height and tilt'], ['Surface', 'non-slip, antimicrobial treatment'], ['Movement', 'lockable or free rocking'], ['Suited to', 'shorter people, fixed-height desks']],
        [['Do I need a footrest?', 'If your feet do not rest flat with the chair at the right height, yes. Otherwise it is not needed.'], ['Rock or lock?', 'Rocking keeps the legs moving, locked gives more support. Try both.'], ['Does it replace an adjustable desk?', 'No, but it compensates well for a desk that is too high.']],
        $bodyEn('Many desks have a fixed height that is too high for shorter people. A footrest is the cheapest correction.', ['Noticeably more relaxed posture', 'Adjustable in height and angle', 'Rocking function for movement'], ['Only useful if your feet would otherwise dangle', 'Needs space under the desk'], 'Desks with a fixed height, and anyone whose feet do not rest flat when seated.'),
    )),

    // --- Unterwegs ----------------------------------------------------------
    $p('unterwegs', 'B0D3WQQRM3', 'Logitech', 'tastatur,tablet,mobil', $t(
        'logitech-keys-to-go-2',
        'Logitech Keys-To-Go 2',
        'Flache Reisetastatur mit Schutzhülle: aus dem Tablet wird ein Schreibgerät.',
        'Logitech Keys-To-Go 2 eingeschätzt: flache Bluetooth-Tastatur mit integrierter Abdeckung für Tablet, Handy und Laptop. Für Notizen und Mails unterwegs.',
        'Die Keys-To-Go 2 ist eine sehr flache Bluetooth-Tastatur mit eingebauter Abdeckung. Sie macht aus Tablet oder Handy ein Schreibgerät für Notizen und Mails und wechselt zwischen bis zu drei Geräten.',
        [['Bauform', 'sehr flach, mit Abdeckung'], ['Verbindung', 'Bluetooth, bis zu 3 Geräte'], ['Strom', 'Batterie mit langer Laufzeit'], ['Geeignet für', 'Tablet, Handy, Laptop']],
        [['Tippt man darauf bequem?', 'Für Notizen und Mails gut. Für lange Texte ist eine Tastatur in voller Größe angenehmer.'], ['Hält sie das Tablet?', 'Nein, sie ist keine Hülle mit Ständer. Ein Tablet-Ständer ist sinnvoll.'], ['Muss ich sie laden?', 'Nein, sie läuft lange mit Batterie.']],
        $bodyDe('Wer unterwegs nur das Tablet dabei hat, tippt auf dem Glas langsam und fehleranfällig. Eine echte Tastatur verdoppelt das Tempo.', ['Sehr flach und leicht', 'Abdeckung schützt die Tasten in der Tasche', 'Kein Laden nötig'], ['Kompakteres Tippgefühl als am Schreibtisch', 'Kein Ständer für das Tablet'], 'Für Berater, Vertrieb und alle, die unterwegs mit Tablet oder Handy Notizen und Mails schreiben.'),
    ), $t(
        'logitech-keys-to-go-2-keyboard',
        'Logitech Keys-To-Go 2',
        'Slim travel keyboard with a protective cover: turns the tablet into a writing device.',
        'Logitech Keys-To-Go 2 assessed: slim Bluetooth keyboard with a built-in cover for tablet, phone and laptop. For notes and emails on the go.',
        'The Keys-To-Go 2 is a very slim Bluetooth keyboard with a built-in cover. It turns a tablet or phone into a writing device for notes and emails and switches between up to three devices.',
        [['Form', 'very slim, with cover'], ['Connection', 'Bluetooth, up to 3 devices'], ['Power', 'long-life battery'], ['Suited to', 'tablet, phone, laptop']],
        [['Is it comfortable to type on?', 'Good for notes and emails. For long texts a full-size keyboard is more comfortable.'], ['Does it hold the tablet?', 'No, it is not a case with a stand. A tablet stand makes sense.'], ['Do I need to charge it?', 'No, it runs for a long time on its battery.']],
        $bodyEn('Anyone carrying only a tablet types slowly and error-prone on glass. A real keyboard doubles the pace.', ['Very slim and light', 'Cover protects the keys in the bag', 'No charging needed'], ['More compact typing feel than at the desk', 'No stand for the tablet'], 'Consultants, sales staff and anyone writing notes and emails on tablet or phone on the go.'),
    )),
    $p('unterwegs', 'B07W6HVQXB', 'Logitech', 'maus,mobil,leise', $t(
