        [['Ist sie für den ganzen Tag geeignet?', 'Für unterwegs ja. Am festen Schreibtisch ist eine größere, ergonomische Maus bequemer.'], ['Brauche ich einen Empfänger?', 'Nein, sie verbindet sich per Bluetooth.'], ['Ist sie wirklich leise?', 'Ja, die Klicks sind kaum hörbar, angenehm im Zug oder in Besprechungen.']],
        $bodyDe('Das Touchpad reicht unterwegs oft nicht, eine große Maus nimmt zu viel Platz. Die Pebble ist der Mittelweg.', ['Flach und leicht', 'Leise Klicks', 'Drei Geräte umschaltbar'], ['Wenig Ergonomie für lange Tage', 'Keine Zusatztasten'], 'Für Laptop-Arbeit im Zug, beim Kunden und im Hotel.'),
    ), $t(
