        [['Brauche ich einen eigenen Vertrag?', 'Ja, eine Daten-SIM. Viele Anbieter haben günstige Zweitkarten oder reine Datentarife.'], ['Warum nicht einfach den Handy-Hotspot?', 'Der Router hält länger durch, versorgt mehr Geräte stabil und schont den Handyakku.'], ['Taugt er als Ersatz bei DSL-Ausfall?', 'Ja, als Notfallnetz für das Büro ist er sehr praktisch.']],
        $bodyDe('Offenes Hotel- oder Messe-WLAN ist langsam und unsicher. Ein eigener 5G-Router gibt Ihnen ein Netz, das Sie kontrollieren.', ['Eigenes, verschlüsseltes WLAN überall', 'Mehrere Geräte gleichzeitig', 'Auch als Notfallnetz bei Ausfall des Festnetzes'], ['Braucht eine eigene SIM mit Datenvolumen', 'Tempo hängt vom Mobilfunknetz vor Ort ab'], 'Für Teams auf Messen und Baustellen, Vielreisende und Büros, die ein Ausweichnetz wollen.'),
