    $p('sicherheit', 'B08J6Q7RHG', 'Kensington', 'sicherheitsschluessel,fido2,fingerabdruck', $t(
        'kensington-verimark-guard-usb-c',
        'Kensington VeriMark Guard USB-C',
        'Sicherheitsschlüssel mit Fingerabdruck: Anmeldung per Berührung, sicher gegen Phishing.',
        'Kensington VeriMark Guard eingeschätzt: FIDO2-Sicherheitsschlüssel mit Fingerabdrucksensor und USB-C. Phishing-sichere Anmeldung per Berührung.',
        'Der VeriMark Guard ist ein FIDO2-Sicherheitsschlüssel mit Fingerabdrucksensor. Statt Code oder PIN bestätigen Sie die Anmeldung mit dem Finger. Er schützt wie andere FIDO-Schlüssel wirksam gegen Phishing.',
        [['Standard', 'FIDO2 / WebAuthn und FIDO U2F'], ['Bestätigung', 'Fingerabdruck'], ['Anschluss', 'USB-C'], ['Geeignet für', 'Microsoft-, Google-Konten, Passwortmanager']],
        [['Worin unterscheidet er sich vom YubiKey?', 'Er bestätigt per Fingerabdruck statt Berührung oder PIN. Dafür fehlen NFC und einige Zusatzfunktionen.'], ['Was passiert, wenn ich ihn verliere?', 'Richten Sie immer einen zweiten Schlüssel oder eine Ersatzmethode ein.'], ['Funktioniert er am Handy?', 'Nur an Geräten mit USB-C, NFC hat er nicht.']],
        $bodyDe('Ein Sicherheitsschlüssel ist der wirksamste Schutz gegen gestohlene Zugangsdaten. Der VeriMark Guard verbindet das mit dem Komfort eines Fingerabdrucks.', ['Phishing-sicher nach FIDO-Standard', 'Bestätigung per Fingerabdruck, keine PIN', 'Kompakt mit USB-C'], ['Kein NFC für Handys ohne USB-C', 'Immer einen Ersatzschlüssel einplanen'], 'Für Selbstständige und Teams, die ihre wichtigsten Konten mit einem Schlüssel schützen und dabei auf PINs verzichten wollen.'),
    ), $t(
        'kensington-verimark-guard-usb-c-key',
        'Kensington VeriMark Guard USB-C',
        'Security key with a fingerprint sensor: sign in with a touch, safe against phishing.',
        'Kensington VeriMark Guard assessed: FIDO2 security key with a fingerprint sensor and USB-C. Phishing-resistant sign-in with a touch.',
        'The VeriMark Guard is a FIDO2 security key with a fingerprint sensor. Instead of a code or PIN you confirm the sign-in with your finger. Like other FIDO keys it protects effectively against phishing.',
        [['Standard', 'FIDO2 / WebAuthn and FIDO U2F'], ['Confirmation', 'fingerprint'], ['Connection', 'USB-C'], ['Suited to', 'Microsoft and Google accounts, password managers']],
        [['How does it differ from a YubiKey?', 'It confirms with a fingerprint instead of a touch or PIN. In return it lacks NFC and some extra functions.'], ['What if I lose it?', 'Always register a second key or a backup method.'], ['Does it work with a phone?', 'Only on devices with USB-C, as it has no NFC.']],
        $bodyEn('A security key is the most effective protection against stolen credentials. The VeriMark Guard combines that with the convenience of a fingerprint.', ['Phishing-resistant to the FIDO standard', 'Fingerprint confirmation, no PIN', 'Compact with USB-C'], ['No NFC for phones without USB-C', 'Always plan for a spare key'], 'Freelancers and teams who protect their key accounts with a security key and want to do without PINs.'),
    )),
    $p('sicherheit', 'B0GXJ4YV43', 'Kensington', 'fingerabdruck,windows-hello,anmeldung', $t(
        'kensington-verimark-desktop-2',
        'Kensington VeriMark Desktop 2.0 Fingerabdruckleser',
        'Fingerabdruckleser für Windows Hello: Desktop-PCs ohne Passworteingabe entsperren.',
        'Kensington VeriMark Desktop 2.0 eingeschätzt: Fingerabdruckleser für Windows Hello an Desktop-PCs. Schnell und sicher anmelden statt Passwort tippen.',
        'Der VeriMark Desktop 2.0 ist ein Fingerabdruckleser für Windows Hello. Er rüstet Desktop-PCs und Laptops ohne Sensor nach: Der Rechner entsperrt sich per Finger, das Passwort bleibt für den Notfall.',
        [['Funktion', 'Fingerabdruck für Windows Hello'], ['Anschluss', 'USB-C und USB-A'], ['Bauform', 'kleiner Tischsensor mit Kabel'], ['Geeignet für', 'Desktop-PCs, Laptops am Dock']],
        [['Ist das sicherer als ein Passwort?', 'Bequemer und schwerer abzuschauen. Wichtig bleibt ein starkes Passwort als Rückfall.'], ['Funktioniert er am Mac?', 'Er ist für Windows Hello gedacht. Für Macs ist Touch ID der passende Weg.'], ['Ersetzt er einen Sicherheitsschlüssel?', 'Nein. Er entsperrt den Rechner. Für Online-Konten ist ein FIDO-Schlüssel der stärkere Schutz.']],
        $bodyDe('Wer den Rechner bei jeder Pause sperrt, tippt das Passwort zig Mal am Tag. Mit Fingerabdruck wird das sichere Verhalten zum bequemen.', ['Entsperren in einer Sekunde', 'Fördert das Sperren bei jeder Pause', 'Für Rechner ohne eingebauten Sensor'], ['Nur für Windows Hello', 'Kein Ersatz für Zwei-Faktor bei Online-Konten'], 'Für Büros mit Desktop-PCs und Laptops am Dock, an denen Windows Hello fehlt.'),
    ), $t(
        'kensington-verimark-desktop-2-fingerprint-reader',
        'Kensington VeriMark Desktop 2.0 fingerprint reader',
        'Fingerprint reader for Windows Hello: unlock desktop PCs without typing a password.',
        'Kensington VeriMark Desktop 2.0 assessed: fingerprint reader for Windows Hello on desktop PCs. Sign in quickly and securely instead of typing a password.',
        'The VeriMark Desktop 2.0 is a fingerprint reader for Windows Hello. It retrofits desktop PCs and laptops without a sensor: the computer unlocks with a finger, and the password stays for emergencies.',
        [['Function', 'fingerprint for Windows Hello'], ['Connection', 'USB-C and USB-A'], ['Form', 'small desk sensor with cable'], ['Suited to', 'desktop PCs, docked laptops']],
        [['Is it more secure than a password?', 'More convenient and harder to shoulder-surf. A strong password as fallback still matters.'], ['Does it work on a Mac?', 'It is designed for Windows Hello. On Macs, Touch ID is the right path.'], ['Does it replace a security key?', 'No. It unlocks the computer. For online accounts a FIDO key is the stronger protection.']],
        $bodyEn('Anyone who locks the computer at every break types the password dozens of times a day. With a fingerprint the secure habit becomes the convenient one.', ['Unlock in a second', 'Encourages locking at every break', 'For computers without a built-in sensor'], ['Windows Hello only', 'No substitute for two-factor on online accounts'], 'Offices with desktop PCs and docked laptops that lack Windows Hello.'),
    )),
    $p('sicherheit', 'B00CTFTG2C', 'Eaton', 'usv,strom,schutz', $t(
        'eaton-ellipse-pro-650',
        'Eaton Ellipse PRO 650 USV',
        'Line-Interactive-USV mit Display: hält Router und NAS bei Stromausfall am Laufen.',
        'Eaton Ellipse PRO 650 eingeschätzt: Line-Interactive-USV mit Schuko-Steckdosen, Display und USB-Abschaltung. Schützt Router, NAS und PC vor Stromausfällen.',
        'Die Eaton Ellipse PRO 650 ist eine Line-Interactive-USV mit Schuko-Steckdosen und Display. Sie glättet Spannungsschwankungen, überbrückt kurze Ausfälle und fährt angeschlossene Rechner per USB kontrolliert herunter.',
        [['Leistung', '650 VA / 400 W'], ['Technik', 'Line-Interactive mit Spannungsregelung'], ['Steckdosen', 'Schuko, mit Batterie und nur Überspannungsschutz'], ['Abschaltung', 'per USB-Software']],
        [['Wie lange hält sie durch?', 'Für Router und NAS einige Minuten bis deutlich länger, je nach Last. Genug, um sauber herunterzufahren.'], ['Was bedeutet Line-Interactive?', 'Sie gleicht Unter- und Überspannung aus, ohne auf Batterie umzuschalten. Das schont den Akku.'], ['Kann ich einen Laserdrucker anschließen?', 'Nein. Laserdrucker ziehen beim Aufheizen zu viel Strom.']],
        $bodyDe('Ein Stromausfall mitten im Schreibvorgang kann ein NAS beschädigen. Eine USV mit Abschaltsignal ist eine kleine Versicherung dagegen.', ['Spannungsregelung ohne Batteriebetrieb', 'Gut ablesbares Display', 'Kontrolliertes Herunterfahren per USB'], ['Für leistungshungrige Geräte zu klein', 'Akku muss nach einigen Jahren getauscht werden'], 'Für Büros mit NAS, Router und Telefonanlage, die bei Stromschwankungen nicht ausfallen sollen.'),
    ), $t(
        'eaton-ellipse-pro-650-ups',
        'Eaton Ellipse PRO 650 UPS',
        'Line-interactive UPS with a display: keeps router and NAS running through a power cut.',
        'Eaton Ellipse PRO 650 assessed: line-interactive UPS with Schuko sockets, display and USB shutdown. Protects router, NAS and PC from power cuts.',
        'The Eaton Ellipse PRO 650 is a line-interactive UPS with Schuko sockets and a display. It smooths voltage fluctuations, bridges short outages and shuts connected computers down cleanly via USB.',
        [['Rating', '650 VA / 400 W'], ['Technology', 'line-interactive with voltage regulation'], ['Sockets', 'Schuko, battery-backed and surge-only'], ['Shutdown', 'via USB software']],
        [['How long does it last?', 'For router and NAS, several minutes or considerably longer depending on load. Enough to shut down cleanly.'], ['What does line-interactive mean?', 'It compensates under- and overvoltage without switching to battery. That spares the battery.'], ['Can I connect a laser printer?', 'No. Laser printers draw too much power while heating up.']],
        $bodyEn('A power cut in the middle of a write can damage a NAS. A UPS with a shutdown signal is a small insurance against that.', ['Voltage regulation without battery use', 'Easy-to-read display', 'Clean shutdown via USB'], ['Too small for power-hungry devices', 'Battery needs replacing after some years'], 'Offices with NAS, router and phone system that should not go down when the power fluctuates.'),
    )),
    $p('sicherheit', 'B0BGXY2NZ4', 'Toshiba', 'festplatte,backup,extern', $t(
        'toshiba-canvio-partner-4tb',
        'Toshiba Canvio Partner 4 TB',
        'Günstige externe Festplatte für die zweite Sicherungskopie, die außer Haus liegt.',
        'Toshiba Canvio Partner 4 TB eingeschätzt: tragbare externe USB-Festplatte für günstige Backups. Gut als Wechselplatte für die Kopie außer Haus.',
        'Die Toshiba Canvio Partner ist eine tragbare externe Festplatte mit 4 TB. Sie bietet viel Speicher für wenig Geld und eignet sich als Wechselplatte: eine liegt im Büro, eine zu Hause.',
        [['Kapazität', '4 TB'], ['Anschluss', 'USB 3.2 Gen 1'], ['Bauform', '2,5 Zoll, Strom über USB'], ['Geeignet für', 'Backups, Archiv, Wechselplatte']],
        [['Warum zwei Platten?', 'Damit immer eine Kopie außerhalb des Büros liegt, falls dort Brand, Diebstahl oder Verschlüsselungstrojaner zuschlagen.'], ['SSD oder Festplatte?', 'Für Backups reicht die günstigere Festplatte. Eine SSD lohnt sich für Arbeit direkt vom Datenträger.'], ['Muss ich sie verschlüsseln?', 'Für Kundendaten ja. Nutzen Sie BitLocker oder die Verschlüsselung Ihres Backup-Programms.']],
        $bodyDe('Die beste Backup-Strategie ist die, die tatsächlich läuft. Zwei günstige Platten im Wechsel sind ein einfacher Anfang.', ['Viel Speicher für wenig Geld', 'Strom über USB, kein Netzteil', 'Kompakt genug für die Schublade zu Hause'], ['Empfindlicher gegen Stürze als eine SSD', 'Keine Hardware-Verschlüsselung'], 'Für Selbstständige und kleine Büros, die ein einfaches Backup mit Kopie außer Haus aufbauen.'),
    ), $t(
        'toshiba-canvio-partner-4tb-hdd',
        'Toshiba Canvio Partner 4 TB',
        'Affordable external hard drive for the second backup copy kept off site.',
        'Toshiba Canvio Partner 4 TB assessed: portable external USB hard drive for affordable backups. Good as a rotating drive for the off-site copy.',
        'The Toshiba Canvio Partner is a portable 4 TB external hard drive. It offers plenty of storage for little money and suits rotation: one drive stays at the office, one at home.',
        [['Capacity', '4 TB'], ['Connection', 'USB 3.2 Gen 1'], ['Form', '2.5 inch, USB-powered'], ['Suited to', 'backups, archive, rotating drive']],
        [['Why two drives?', 'So one copy is always outside the office in case of fire, theft or ransomware there.'], ['SSD or hard drive?', 'For backups the cheaper hard drive is enough. An SSD pays off for working directly from the drive.'], ['Do I need to encrypt it?', 'For client data yes. Use BitLocker or your backup software\'s encryption.']],
        $bodyEn('The best backup strategy is the one that actually runs. Two cheap drives in rotation are a simple start.', ['Plenty of storage for little money', 'USB-powered, no adapter', 'Compact enough for a drawer at home'], ['More sensitive to drops than an SSD', 'No hardware encryption'], 'Freelancers and small offices setting up a simple backup with an off-site copy.'),
    )),
    $p('sicherheit', 'B0CGQ43PMG', 'Samsung', 'ssd,extern,backup', $t(
