        [['Mit welchen Anbietern funktioniert es?', 'Mit allen SIP-Telefonanlagen, etwa sipgate, Placetel oder der FRITZ!Box.'], ['Brauche ich ein Netzteil?', 'Nicht mit PoE-Switch. Ohne PoE ist ein separates Netzteil nötig.'], ['Kann ich ein Headset anschließen?', 'Ja, per Bluetooth oder Kabel.']],
        $bodyDe('Mit dem Wechsel zu Cloud-Telefonanlagen brauchen Büros Telefone, die SIP sprechen. Snom aus Berlin ist dafür eine bewährte Marke.', ['Viele belegbare Tasten mit Statusanzeige', 'Strom über das Netzwerkkabel', 'Bluetooth für Headsets'], ['Netzteil bei fehlendem PoE extra', 'Einrichtung braucht die SIP-Daten Ihres Anbieters'], 'Für Büros mit Cloud-Telefonanlage, Empfang und Teams, die viel telefonieren und weiterverbinden.'),
    ), $t(
        'snom-d785-ip-phone',
        'Snom D785 IP desk phone',
        'SIP desk phone with colour display and Bluetooth: the solid office phone for cloud phone systems.',
        'Snom D785 assessed: SIP desk phone with colour display, Bluetooth, Gigabit and PoE. For cloud phone systems and the FRITZ!Box as an IP phone.',
        'The Snom D785 is a SIP desk phone with a colour display, Bluetooth and PoE. It works with cloud phone systems and the FRITZ!Box and offers many assignable keys for colleagues and functions.',
        [['Protocol', 'SIP, up to 12 identities'], ['Display', 'colour display plus key display'], ['Network', 'Gigabit, PoE'], ['Extras', 'Bluetooth for headsets']],
        [['Which providers does it work with?', 'With any SIP phone system, such as sipgate, Placetel or the FRITZ!Box.'], ['Do I need a power adapter?', 'Not with a PoE switch. Without PoE a separate adapter is required.'], ['Can I connect a headset?', 'Yes, via Bluetooth or cable.']],
        $bodyEn('With the move to cloud phone systems, offices need phones that speak SIP. Snom from Berlin is a proven brand for that.', ['Many assignable keys with status display', 'Power over the network cable', 'Bluetooth for headsets'], ['Adapter extra without PoE', 'Setup needs your provider\'s SIP details'], 'Offices with a cloud phone system, reception desks and teams that call and transfer a lot.'),
    )),
    $p('buero', 'B0DG9ZXWMK', 'reMarkable', 'notizen,e-ink,papierlos', $t(
        'remarkable-paper-pro',
        'reMarkable Paper Pro mit Marker Plus',
        'Digitales Papier mit Farbdisplay: handschriftliche Notizen und PDFs ohne Ablenkung.',
        'reMarkable Paper Pro eingeschätzt: E-Ink-Tablet mit Farbdisplay und Stift für Notizen, Skizzen und PDF-Anmerkungen. Papierloses Arbeiten ohne Ablenkung.',
        'Das reMarkable Paper Pro ist ein E-Ink-Tablet mit Farbdisplay und Stift. Es schreibt sich wie Papier, zeigt keine Benachrichtigungen und eignet sich für Notizen, Skizzen und das Kommentieren von PDFs.',
        [['Display', 'Farb-E-Ink, beleuchtet'], ['Stift', 'Marker Plus mit Radierer'], ['Formate', 'Notizbücher, PDF, E-Books'], ['Abgleich', 'App für Rechner und Handy']],
        [['Ersetzt es ein iPad?', 'Nein. Es kann bewusst wenig: Schreiben, Lesen, Anmerken. Genau das macht es konzentriert.'], ['Brauche ich ein Abo?', 'Für den Grundbetrieb nicht. Einige Funktionen wie unbegrenzter Cloud-Speicher setzen ein Abo voraus.'], ['Kann ich Handschrift in Text umwandeln?', 'Ja, die Handschrifterkennung ist eingebaut.']],
        $bodyDe('Viele denken auf Papier besser, verlieren aber Zettel und Notizbücher. Das reMarkable verbindet das Schreibgefühl mit digitaler Ablage.', ['Schreibgefühl sehr nah an Papier', 'Keine Ablenkung durch Apps und Mitteilungen', 'PDFs direkt kommentieren'], ['Hoher Preis für ein Spezialgerät', 'Manche Funktionen nur mit Abo'], 'Für Berater, Projektleiter und alle, die viel handschriftlich denken, notieren und Dokumente prüfen.'),
    ), $t(
        'remarkable-paper-pro-tablet',
        'reMarkable Paper Pro with Marker Plus',
        'Digital paper with a colour display: handwritten notes and PDFs without distraction.',
        'reMarkable Paper Pro assessed: E Ink tablet with colour display and pen for notes, sketches and PDF annotation. Paperless work without distraction.',
        'The reMarkable Paper Pro is an E Ink tablet with a colour display and pen. It writes like paper, shows no notifications and suits notes, sketches and annotating PDFs.',
        [['Display', 'colour E Ink, front-lit'], ['Pen', 'Marker Plus with eraser'], ['Formats', 'notebooks, PDF, e-books'], ['Sync', 'app for computer and phone']],
        [['Does it replace an iPad?', 'No. It deliberately does little: writing, reading, annotating. That is what keeps you focused.'], ['Do I need a subscription?', 'Not for basic use. Some functions such as unlimited cloud storage require one.'], ['Can I convert handwriting to text?', 'Yes, handwriting recognition is built in.']],
        $bodyEn('Many people think better on paper but lose notes and notebooks. The reMarkable combines the writing feel with digital filing.', ['Writing feel very close to paper', 'No distraction from apps or notifications', 'Annotate PDFs directly'], ['High price for a specialist device', 'Some functions only with a subscription'], 'Consultants, project leads and anyone who thinks, notes and reviews documents by hand.'),
    )),

    // --- Foto, Video & Social Media -----------------------------------------
    $p('content', 'B0FKTBGNR8', 'DJI', 'kamera,gimbal,video', $t(
        'dji-osmo-pocket-4',
        'DJI Osmo Pocket 4 Standard Combo',
        'Kamera mit eingebautem Gimbal im Hosentaschenformat: ruhige Videos für Social Media und Website.',
        'DJI Osmo Pocket 4 eingeschätzt: kompakte 4K-Kamera mit mechanischem Gimbal für ruhige Videos. Für Reels, Produktvideos und Einblicke in den Betrieb.',
        'Die DJI Osmo Pocket 4 ist eine kompakte 4K-Kamera mit eingebautem mechanischem Gimbal. Sie filmt auch aus der Hand ruhig, folgt Gesichtern automatisch und passt in jede Tasche.',
        [['Video', '4K'], ['Stabilisierung', 'mechanischer 3-Achsen-Gimbal'], ['Bedienung', 'drehbarer Touchscreen, Gesichtsverfolgung'], ['Geeignet für', 'Reels, Produktvideos, Werkstatt-Einblicke']],
        [['Reicht nicht das Handy?', 'Für vieles ja. Die Pocket filmt ruhiger, bei wenig Licht besser und blockiert das Handy nicht.'], ['Brauche ich ein Mikrofon dazu?', 'Für Sprache lohnt sich ein Funkmikrofon. DJI-Mikrofone verbinden sich direkt.'], ['Ist sie kompliziert?', 'Nein. Einschalten, ausrichten, aufnehmen. Die Automatik erledigt den Rest.']],
        $bodyDe('Videos aus dem Betrieb wirken nahbar, wenn sie ruhig und klar sind. Die Pocket-Serie ist dafür die einfachste Profi-Lösung.', ['Sehr ruhige Aufnahmen ohne Stativ', 'Automatische Gesichtsverfolgung', 'Winzig und schnell einsatzbereit'], ['Für Sprache ein externes Mikrofon einplanen', 'Teurer als ein Handy-Gimbal'], 'Für Handwerk, Gastronomie, Coaches und alle, die regelmäßig kurze Videos für Social Media und Website drehen.'),
    ), $t(
        'dji-osmo-pocket-4-camera',
        'DJI Osmo Pocket 4 Standard Combo',
        'Pocket-sized camera with a built-in gimbal: steady videos for social media and website.',
        'DJI Osmo Pocket 4 assessed: compact 4K camera with a mechanical gimbal for steady video. For reels, product videos and glimpses behind the scenes.',
        'The DJI Osmo Pocket 4 is a compact 4K camera with a built-in mechanical gimbal. It films steadily even handheld, follows faces automatically and fits in any pocket.',
        [['Video', '4K'], ['Stabilisation', 'mechanical 3-axis gimbal'], ['Controls', 'rotating touchscreen, face tracking'], ['Suited to', 'reels, product videos, workshop glimpses']],
        [['Is a phone not enough?', 'For much, yes. The Pocket films more steadily, better in low light and keeps your phone free.'], ['Do I need a microphone?', 'For speech a wireless microphone pays off. DJI microphones connect directly.'], ['Is it complicated?', 'No. Switch on, point, record. The automatics do the rest.']],
        $bodyEn('Videos from your business feel approachable when they are steady and clear. The Pocket series is the simplest professional answer.', ['Very steady footage without a tripod', 'Automatic face tracking', 'Tiny and ready in seconds'], ['Plan for an external microphone for speech', 'Pricier than a phone gimbal'], 'Trades, hospitality, coaches and anyone regularly shooting short videos for social media and website.'),
    )),
    $p('content', 'B0FJ2L67HJ', 'DJI', 'gimbal,smartphone,video', $t(
        'dji-osmo-mobile-8',
        'DJI Osmo Mobile 8 Smartphone-Gimbal',
        'Gimbal für das Handy: ruhige Kamerafahrten und automatisches Mitverfolgen mit der Kamera, die Sie schon haben.',
        'DJI Osmo Mobile 8 eingeschätzt: 3-Achsen-Gimbal für Smartphones mit Motivverfolgung. Ruhige Handyvideos für Social Media zum kleinen Preis.',
        'Der DJI Osmo Mobile 8 ist ein 3-Achsen-Gimbal für das Smartphone. Er gleicht Wackler aus, folgt Personen automatisch und macht aus dem Handy eine ruhige Videokamera.',
        [['Stabilisierung', '3 Achsen'], ['Verfolgung', 'automatische Motivverfolgung'], ['Bauform', 'faltbar'], ['Geeignet für', 'iPhone und Android']],
        [['Brauche ich eine App?', 'Für einige Funktionen ja. Die Motivverfolgung funktioniert je nach Modell auch mit der normalen Kamera-App.'], ['Passt mein Handy?', 'Die meisten Smartphones passen. Sehr schwere Modelle mit dicker Hülle sollten Sie vorher prüfen.'], ['Gimbal oder Pocket-Kamera?', 'Gimbal, wenn das Handy eine gute Kamera hat. Pocket, wenn Sie ein eigenes Gerät wollen.']],
        $bodyDe('Die Kamera im Handy ist längst gut genug für Social Media. Was fehlt, ist ein ruhiges Bild. Ein Gimbal liefert genau das.', ['Ruhige Aufnahmen aus der Hand', 'Automatische Verfolgung für Solo-Aufnahmen', 'Faltbar für die Tasche'], ['Nur so gut wie die Handykamera', 'Handy ist während der Aufnahme belegt'], 'Für alle, die mit ihrem Smartphone regelmäßig Videos für Instagram, TikTok oder die Website drehen.'),
    ), $t(
        'dji-osmo-mobile-8-gimbal',
        'DJI Osmo Mobile 8 smartphone gimbal',
        'Gimbal for your phone: steady camera moves and automatic tracking with the camera you already have.',
        'DJI Osmo Mobile 8 assessed: 3-axis smartphone gimbal with subject tracking. Steady phone videos for social media at a small price.',
        'The DJI Osmo Mobile 8 is a 3-axis gimbal for the smartphone. It smooths out shakes, follows people automatically and turns the phone into a steady video camera.',
        [['Stabilisation', '3 axes'], ['Tracking', 'automatic subject tracking'], ['Form', 'foldable'], ['Suited to', 'iPhone and Android']],
        [['Do I need an app?', 'For some functions yes. Depending on the model, tracking also works with the normal camera app.'], ['Will my phone fit?', 'Most smartphones fit. Check very heavy models with thick cases beforehand.'], ['Gimbal or pocket camera?', 'Gimbal if your phone has a good camera. Pocket if you want a separate device.']],
        $bodyEn('Phone cameras have long been good enough for social media. What is missing is a steady picture. A gimbal delivers exactly that.', ['Steady handheld footage', 'Automatic tracking for solo shoots', 'Foldable for the bag'], ['Only as good as the phone camera', 'Phone is tied up while recording'], 'Anyone regularly shooting videos for Instagram, TikTok or the website with a smartphone.'),
    )),
    $p('content', 'B0G39FV1HL', 'DJI', 'mikrofon,funk,video', $t(
        'dji-mic-mini-2',
        'DJI Mic Mini 2 Funkmikrofon (2 Sender)',
        'Zwei winzige Ansteckmikrofone mit Empfänger fürs Handy: klare Stimme in jedem Video.',
        'DJI Mic Mini 2 eingeschätzt: kabelloses Ansteck-Funkmikrofon mit zwei Sendern und Handy-Empfänger. Der größte Qualitätssprung für Videos mit Sprache.',
        'Das DJI Mic Mini 2 ist ein Funkmikrofon-Set mit zwei winzigen Ansteck-Sendern und einem Empfänger für das Handy. Es nimmt die Stimme direkt am Körper auf und blendet Umgebungsgeräusche weitgehend aus.',
        [['Umfang', '2 Sender, 1 Handy-Empfänger, Ladeschale'], ['Befestigung', 'Clip oder Magnet'], ['Ton', 'Rauschunterdrückung'], ['Geeignet für', 'Interviews, Erklärvideos, Reels']],
        [['Warum ein Mikrofon statt des Handy-Mikros?', 'Weil der Ton am Körper aufgenommen wird. Hall und Umgebungslärm verschwinden weitgehend.'], ['Wozu zwei Sender?', 'Für Interviews und Gespräche, oder als Reserve.'], ['Passt der Empfänger an mein Handy?', 'Der Handy-Empfänger steckt im USB-C-Anschluss. Für Lightning-iPhones gibt es Adapter.']],
        $bodyDe('Zuschauer verzeihen ein mittelmäßiges Bild, aber keinen schlechten Ton. Ein Ansteckmikrofon ist deshalb die wichtigste Anschaffung für Videos.', ['Winzig und kaum sichtbar', 'Zwei Sender für Gespräche', 'Ladeschale wie bei Ohrhörern'], ['Empfänger belegt den Ladeanschluss des Handys', 'Für Kameras ohne passenden Eingang den Standard-Empfänger wählen'], 'Für alle, die in Videos sprechen: Erklärvideos, Interviews, Kundenstimmen, Reels.'),
    ), $t(
        'dji-mic-mini-2-wireless',
        'DJI Mic Mini 2 wireless microphone (2 transmitters)',
        'Two tiny clip-on mics with a phone receiver: a clear voice in every video.',
        'DJI Mic Mini 2 assessed: wireless clip-on microphone set with two transmitters and a phone receiver. The biggest quality jump for videos with speech.',
        'The DJI Mic Mini 2 is a wireless microphone set with two tiny clip-on transmitters and a receiver for the phone. It records your voice right at the body and largely suppresses background noise.',
        [['Contents', '2 transmitters, 1 phone receiver, charging case'], ['Mounting', 'clip or magnet'], ['Sound', 'noise reduction'], ['Suited to', 'interviews, explainer videos, reels']],
        [['Why a microphone instead of the phone mic?', 'Because sound is recorded at the body. Echo and background noise largely disappear.'], ['Why two transmitters?', 'For interviews and conversations, or as a spare.'], ['Will the receiver fit my phone?', 'The phone receiver plugs into USB-C. Adapters exist for Lightning iPhones.']],
        $bodyEn('Viewers forgive a mediocre picture but not bad sound. A clip-on microphone is therefore the most important purchase for video.', ['Tiny and barely visible', 'Two transmitters for conversations', 'Charging case like earbuds'], ['Receiver occupies the phone\'s charging port', 'For cameras without a matching input choose the standard receiver'], 'Anyone speaking in videos: explainers, interviews, testimonials, reels.'),
    )),
    $p('content', 'B0CTJ7PVN1', 'Shure', 'mikrofon,podcast,usb', $t(
        'shure-mv7-plus',
        'Shure MV7+ Podcast-Mikrofon',
        'Dynamisches Mikrofon mit USB-C und XLR: Radioklang für Podcast, Webinar und Sprachaufnahme.',
        'Shure MV7+ eingeschätzt: dynamisches Podcast-Mikrofon mit USB-C und XLR, Auto-Pegel und Rauschfilter. Klare Stimme auch in nicht gedämmten Räumen.',
        'Das Shure MV7+ ist ein dynamisches Mikrofon mit USB-C- und XLR-Anschluss. Es nimmt vor allem die Stimme direkt davor auf und blendet Raumhall aus. Automatischer Pegel und Rauschfilter erleichtern den Einstieg.',
        [['Typ', 'dynamisch, Niere'], ['Anschlüsse', 'USB-C und XLR'], ['Funktionen', 'automatischer Pegel, Rauschunterdrückung'], ['Geeignet für', 'Podcasts, Webinare, Hörbuch- und Sprachaufnahmen']],
        [['Dynamisch oder Kondensator?', 'Dynamisch, wenn der Raum hallt oder es Nebengeräusche gibt. Es nimmt weniger Raum auf.'], ['Brauche ich ein Audio-Interface?', 'Nein. USB-C reicht. XLR ist für später, wenn Sie aufrüsten.'], ['Wie nah muss ich sprechen?', 'Nah, etwa eine Handbreit. Ein Mikrofonarm hilft dabei.']],
        $bodyDe('Ein eigener Podcast oder regelmäßige Webinare leben von der Stimme. Das MV7+ klingt auch in normalen Büros gut, ohne Akustikdämmung.', ['Klarer, voller Stimmklang', 'USB-C für den Start, XLR für später', 'Unempfindlich gegen Raumhall'], ['Braucht Sprechabstand von einer Handbreit', 'Arm oder Stativ separat einplanen'], 'Für Podcasts, Webinare und Sprachaufnahmen in Räumen ohne Studio-Akustik.'),
    ), $t(
        'shure-mv7-plus-microphone',
        'Shure MV7+ podcast microphone',
        'Dynamic microphone with USB-C and XLR: broadcast sound for podcasts, webinars and voice recordings.',
        'Shure MV7+ assessed: dynamic podcast microphone with USB-C and XLR, auto level and noise filter. A clear voice even in untreated rooms.',
        'The Shure MV7+ is a dynamic microphone with USB-C and XLR connections. It mainly picks up the voice directly in front and ignores room echo. Automatic level and a noise filter make getting started easy.',
        [['Type', 'dynamic, cardioid'], ['Connections', 'USB-C and XLR'], ['Features', 'automatic level, noise reduction'], ['Suited to', 'podcasts, webinars, audiobook and voice recordings']],
        [['Dynamic or condenser?', 'Dynamic if the room echoes or there is background noise. It picks up less of the room.'], ['Do I need an audio interface?', 'No. USB-C is enough. XLR is for later, when you upgrade.'], ['How close do I need to speak?', 'Close, about a hand\'s width. A mic arm helps.']],
        $bodyEn('A podcast or regular webinars live on the voice. The MV7+ sounds good even in ordinary offices, without acoustic treatment.', ['Clear, full voice', 'USB-C to start, XLR for later', 'Resistant to room echo'], ['Needs a hand\'s width speaking distance', 'Plan for an arm or stand separately'], 'Podcasts, webinars and voice recordings in rooms without studio acoustics.'),
    )),
    $p('content', 'B0CW1S7XP5', 'Elgato', 'webcam,full-hd,hdr', $t(
        'elgato-facecam-mk2',
        'Elgato Facecam MK.2 Webcam',
        'Full-HD-Webcam mit Einstellungen wie eine Kamera: scharfes, natürliches Bild für Calls und Aufnahmen.',
        'Elgato Facecam MK.2 eingeschätzt: Full-HD-Webcam mit HDR und manuellen Kameraeinstellungen. Natürliches Bild für Calls, Webinare und Aufnahmen.',
        'Die Elgato Facecam MK.2 ist eine Full-HD-Webcam mit HDR und manuellen Einstellungen für Belichtung, Weißabgleich und Bildausschnitt. Sie liefert ein ruhiges, natürliches Bild ohne die übliche Webcam-Automatik.',
        [['Auflösung', 'Full HD, bis 60 Bilder/s'], ['Bild', 'HDR, manuelle Einstellungen'], ['Anschluss', 'USB-C'], ['Geeignet für', 'Calls, Webinare, Aufnahmen am Schreibtisch']],
        [['Warum nicht 4K?', 'Calls übertragen ohnehin kaum mehr als Full HD. Wichtiger sind Optik und Bildruhe.'], ['Brauche ich die Software?', 'Für die Einstellungen ja. Sie werden in der Kamera gespeichert und gelten dann überall.'], ['Hilft sie bei schlechtem Licht?', 'Etwas. Mehr bringt eine Leuchte von vorn.']],
        $bodyDe('Viele Webcams regeln ständig nach und lassen das Bild pumpen. Die Facecam behält die Einstellungen, die Sie einmal festlegen.', ['Ruhiges, natürliches Bild', 'Einstellungen bleiben in der Kamera', 'Gute Optik statt Pixelrekord'], ['Kein eingebautes Mikrofon', 'Fester Fokus, nicht für Nahaufnahmen von Produkten'], 'Für alle, die regelmäßig Webinare geben oder am Schreibtisch Videos aufnehmen.'),
    ), $t(
        'elgato-facecam-mk2-webcam',
        'Elgato Facecam MK.2 webcam',
        'Full HD webcam with camera-style settings: a sharp, natural picture for calls and recordings.',
        'Elgato Facecam MK.2 assessed: Full HD webcam with HDR and manual camera settings. A natural picture for calls, webinars and recordings.',
        'The Elgato Facecam MK.2 is a Full HD webcam with HDR and manual settings for exposure, white balance and framing. It delivers a steady, natural picture without the usual webcam automatics.',
        [['Resolution', 'Full HD, up to 60 fps'], ['Picture', 'HDR, manual settings'], ['Connection', 'USB-C'], ['Suited to', 'calls, webinars, desk recordings']],
        [['Why not 4K?', 'Calls hardly transmit more than Full HD anyway. Optics and a steady picture matter more.'], ['Do I need the software?', 'For the settings yes. They are stored in the camera and then apply everywhere.'], ['Does it help in poor light?', 'Somewhat. A light from the front helps more.']],
        $bodyEn('Many webcams constantly readjust and make the picture pump. The Facecam keeps the settings you choose once.', ['Steady, natural picture', 'Settings stay in the camera', 'Good optics instead of a pixel record'], ['No built-in microphone', 'Fixed focus, not for product close-ups'], 'Anyone who gives webinars regularly or records videos at the desk.'),
    )),
    $p('content', 'B0CVYD9HB4', 'Elgato', 'licht,led,videocall', $t(
        'elgato-key-light-neo',
        'Elgato Key Light Neo mit Monitorhalterung',
        'Kompaktes Studiolicht für den Monitor: weiches, steuerbares Licht für Calls und Aufnahmen.',
        'Elgato Key Light Neo eingeschätzt: kompakte LED-Leuchte mit Monitorhalterung, steuerbar per App. Gleichmäßiges Licht für Calls, Webinare und Videos.',
        'Das Elgato Key Light Neo ist eine kompakte LED-Leuchte mit Monitorhalterung. Helligkeit und Farbtemperatur steuern Sie per App, das Licht fällt weich und gleichmäßig auf Ihr Gesicht.',
        [['Montage', 'Monitorhalterung'], ['Steuerung', 'App, Helligkeit und Farbtemperatur'], ['Licht', 'weich, flächig'], ['Geeignet für', 'Calls, Webinare, Schreibtisch-Videos']],
        [['Eine oder zwei Leuchten?', 'Eine reicht für Calls. Für Videos wirken zwei Leuchten von links und rechts gleichmäßiger.'], ['Neo oder Key Light Air?', 'Die Neo sitzt kompakt am Monitor, die Air steht auf eigenem Fuß und leuchtet größer.'], ['Wird sie warm?', 'Kaum, LEDs bleiben kühl.']],
        $bodyDe('Gutes Licht ist der schnellste Weg zu einem professionellen Bild. Die Key Light Neo bringt Studiolicht auf kleinsten Raum.', ['Weiches, gleichmäßiges Licht', 'Platzsparend am Monitor', 'Bequem per App steuerbar'], ['Für große Räume zu klein', 'App für alle Einstellungen nötig'], 'Für Schreibtische, an denen regelmäßig Calls, Webinare oder kurze Videos entstehen.'),
    ), $t(
        'elgato-key-light-neo-monitor',
        'Elgato Key Light Neo with monitor mount',
        'Compact studio light for the monitor: soft, controllable light for calls and recordings.',
        'Elgato Key Light Neo assessed: compact LED light with monitor mount, controlled by app. Even lighting for calls, webinars and videos.',
        'The Elgato Key Light Neo is a compact LED light with a monitor mount. Brightness and colour temperature are controlled by app, and the light falls softly and evenly on your face.',
        [['Mounting', 'monitor mount'], ['Control', 'app, brightness and colour temperature'], ['Light', 'soft, diffused'], ['Suited to', 'calls, webinars, desk videos']],
        [['One light or two?', 'One is enough for calls. For videos two lights from left and right look more even.'], ['Neo or Key Light Air?', 'The Neo sits compactly on the monitor, the Air stands on its own pole and lights a larger area.'], ['Does it get warm?', 'Hardly, LEDs stay cool.']],
        $bodyEn('Good light is the quickest way to a professional picture. The Key Light Neo brings studio light into the smallest space.', ['Soft, even light', 'Space-saving on the monitor', 'Convenient app control'], ['Too small for large rooms', 'App needed for all settings'], 'Desks where calls, webinars or short videos happen regularly.'),
    )),
    $p('content', 'B0BQN7CMDJ', 'Manfrotto', 'stativ,smartphone,video', $t(
        'manfrotto-pixi-smartphone-kit',
        'Manfrotto PIXI Mini-Stativ mit Smartphone-Klemme',
        'Kleines, stabiles Tischstativ mit Handyklemme: ruhige Aufnahmen und Hände frei.',
        'Manfrotto PIXI mit Smartphone-Klemme eingeschätzt: kompaktes Tischstativ aus Italien mit universeller Handyhalterung. Für Videos, Calls und Fotos.',
        'Das Manfrotto PIXI ist ein kompaktes Tischstativ mit universeller Smartphone-Klemme. Es hält Handy oder kleine Kamera ruhig auf dem Tisch und dient zusammengeklappt als Handgriff.',
        [['Bauform', 'Mini-Tischstativ, klappbar'], ['Halterung', 'universelle Smartphone-Klemme, Kameragewinde'], ['Herkunft', 'Made in Italy'], ['Geeignet für', 'Videos am Tisch, Produktfotos, Calls']],
        [['Passt mein Handy in die Klemme?', 'Die Klemme ist verstellbar und passt für die meisten Smartphones, auch mit Hülle.'], ['Ist es hoch genug?', 'Für Aufnahmen am Tisch ja. Für Aufnahmen im Stehen brauchen Sie ein großes Stativ.'], ['Hält es eine Kamera?', 'Kleine Kameras wie die DJI Pocket oder spiegellose Kompakte ja.']],
        $bodyDe('Ein Handy an die Kaffeetasse zu lehnen, ist kein Videosetup. Das PIXI ist das kleinste Stativ, das wirklich stabil steht.', ['Sehr stabil für die Größe', 'Klappt zum Handgriff zusammen', 'Klemme passt an fast jedes Handy'], ['Nur für Aufnahmen am Tisch', 'Keine Höhenverstellung'], 'Für Produktfotos, Tischvideos und alle, die beim Filmen die Hände frei haben wollen.'),
    ), $t(
        'manfrotto-pixi-smartphone-clamp-kit',
        'Manfrotto PIXI mini tripod with smartphone clamp',
        'Small, sturdy table tripod with a phone clamp: steady shots with your hands free.',
        'Manfrotto PIXI with smartphone clamp assessed: compact Italian table tripod with a universal phone holder. For videos, calls and photos.',
